package local.headunit.diplay;
import android.content.*;import android.media.AudioManager;import java.io.Closeable;import org.json.JSONObject;
/** Read-only source/focus evidence. Never records phone numbers or contact payloads. */
public final class OemAudioObserver extends BroadcastReceiver implements Closeable {
 private final Context context;private boolean registered;
 public OemAudioObserver(Context c){context=c.getApplicationContext();IntentFilter f=new IntentFilter("APP_REV_DATA");f.addAction("APP_REV_BT_DATA");f.addAction("android.intent.action.MULTIMEDIA_AUDIO_FOCUS_INFO");f.addAction("android.intent.action.MULTIMEDIA_NAVI_AUDIO_START");f.addAction("android.intent.action.MULTIMEDIA_NAVI_AUDIO_STOP");context.registerReceiver(this,f);registered=true;}
 public void onReceive(Context c,Intent i){try{String action=i.getAction();JSONObject d=new JSONObject().put("action",action);if(action.equals("APP_REV_DATA")||action.equals("APP_REV_BT_DATA")){byte[] b=i.getByteArrayExtra("list");if(b==null||b.length<2)return;int group=b[0]&255,command=b[1]&255;if(group!=2&&!(action.equals("APP_REV_DATA")&&group==3&&command==6))return;d.put("group",group).put("command",command);if(action.equals("APP_REV_DATA")&&b.length>=3)d.put("sourceOrVolume",b[2]&255);}if("android.intent.action.MULTIMEDIA_AUDIO_FOCUS_INFO".equals(action)){String pkg=i.getStringExtra("android.intent.extra.MULTIMEDIA_PACKAGE_NAME");if(pkg!=null&&pkg.length()<=160&&pkg.matches("[A-Za-z0-9_.]+"))d.put("reportedPackage",pkg);d.put("reportedGain",i.getIntExtra("android.intent.extra.MULTIMEDIA_AUDIO_FOCUS_TYPE",-1)).put("evidence","oem_broadcast_not_authenticated_owner");}AudioManager a=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);d.put("mode",a.getMode()).put("sco",a.isBluetoothScoOn()).put("speaker",a.isSpeakerphoneOn());MainActivity.record(c,"OEM_AUDIO_STATE",d);}catch(Exception ignored){}}
 public void close(){if(registered){registered=false;try{context.unregisterReceiver(this);}catch(Exception ignored){}}}
}
